+.notice {
+  display: grid;
+  gap: 9px;
+  justify-items: start;
+  padding: 18px 19px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 7px;
+  background: var(--thorp-surface-raised);
+}
+
+.message {
+  margin: 0;
+  color: var(--thorp-foreground);
+  font-size: 0.88rem;
+  font-weight: 700;
+}
+
+.detail {
+  margin: 0;
+  color: var(--thorp-copy);
+  font-size: 0.76rem;
+  line-height: 1.55;
+}
+
+.retry {
+  min-height: 36px;
+  padding: 0 15px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 5px;
+  background: transparent;
+  color: var(--thorp-foreground);
+  cursor: pointer;
+  font-size: 0.76rem;
+  font-weight: 700;
+}
+
+.retry:hover:not(:disabled) {
+  border-color: var(--thorp-accent-soft);
+}
+
+.retry:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+.retry:disabled {
+  color: var(--thorp-muted);
+  cursor: progress;
+}

@@ -0,0 +1,72 @@
+.card {
+  display: grid;
+  gap: 7px;
+  width: 100%;
+  padding: 16px 17px;
+  border: 1px solid var(--thorp-line-strong);
+  border-radius: 7px;
+  background: var(--thorp-surface);
+  cursor: pointer;
+  text-align: left;
+}
+
+.card:hover[data-selectable='true'] {
+  border-color: var(--thorp-accent-soft);
+}
+
+.card:focus-visible {
+  outline: var(--thorp-focus-outline);
+  outline-offset: var(--thorp-focus-offset-compact);
+}
+
+.card[data-selected='true'] {
+  border-color: var(--thorp-accent);
+  box-shadow: inset 0 0 0 1px var(--thorp-accent);
+}
+
+/* 고를 수 없는 카드는 흐려 보이되 초점과 문구는 그대로 읽힌다. */
+.card[data-selectable='false'] {
+  cursor: not-allowed;
+  background: var(--thorp-surface-raised);
+}
+
+.card[data-selectable='false'] .name,
+.card[data-selectable='false'] .description {
+  color: var(--thorp-muted);
+}
+
+.name {
+  color: var(--thorp-foreground);
+  font-size: 0.92rem;
+  font-weight: 700;
+}
+
+.description {
+  color: var(--thorp-copy);
+  font-size: 0.76rem;
+  line-height: 1.55;
+}
+
+.notice {
+  display: grid;
+  gap: 5px;
+  margin-top: 3px;
+}
+
+.reason {
+  display: grid;
+  gap: 3px;
+  color: var(--thorp-copy);
+  font-size: 0.72rem;
+  line-height: 1.5;
+}
+
+.reasonLabel {
+  color: var(--thorp-warning);
+  font-size: 0.66rem;
+  font-weight: 700;
+}
+
+.card[data-selectable='false'] .reasonLabel {
+  color: var(--thorp-neutral);
+}

